window.DV_TOPICS=window.DV_TOPICS||{};window.DV_TOPICS["household-budget"]={"id":"household-budget","order":1,"title_en":"Household Budget","title_zh":"家庭预算","blurb_zh":"一份月收入的分流去向","scene_zh":"一个双收入家庭的月度收支（模拟数据）","views":[{"id":"flows","type":"sankey","label_zh":"收入流向","label_en":"Where income goes","subject":"Household income","subtitle_en":"How monthly income splits across spending blocks.","unit":{"en":"CNY a month","short":"¥","decimals":0,"kind":"count"},"data":{"columns":[["salary","partner","freelance"],["commitments","family","flexible"],["rent","utilities","transport","food","childcare","other"]],"nodes":[{"id":"salary","name_en":"Salary","name_zh":"工资","column":0,"slot":1},{"id":"partner","name_en":"Partner income","name_zh":"伴侣收入","column":0,"slot":2},{"id":"freelance","name_en":"Freelance","name_zh":"兼职收入","column":0,"slot":3},{"id":"commitments","name_en":"Commitments","name_zh":"固定支出","column":1,"slot":4},{"id":"family","name_en":"Family","name_zh":"家庭支出","column":1,"slot":5},{"id":"flexible","name_en":"Flexible","name_zh":"弹性支出","column":1,"slot":6},{"id":"rent","name_en":"Rent","name_zh":"房租","column":2,"slot":1},{"id":"utilities","name_en":"Utilities","name_zh":"水电","column":2,"slot":2},{"id":"transport","name_en":"Transport","name_zh":"交通","column":2,"slot":3},{"id":"food","name_en":"Food","name_zh":"餐饮","column":2,"slot":4},{"id":"childcare","name_en":"Childcare","name_zh":"育儿","column":2,"slot":5},{"id":"other","name_en":"Other","name_zh":"其他","column":2,"slot":6}],"links":[{"source":"salary","target":"commitments","value":11000},{"source":"salary","target":"family","value":5500},{"source":"salary","target":"flexible","value":5500},{"source":"partner","target":"commitments","value":2000},{"source":"partner","target":"family","value":2500},{"source":"partner","target":"flexible","value":2000},{"source":"freelance","target":"commitments","value":500},{"source":"freelance","target":"flexible","value":1000},{"source":"commitments","target":"rent","value":9000},{"source":"commitments","target":"utilities","value":1300},{"source":"commitments","target":"transport","value":1700},{"source":"commitments","target":"food","value":1500},{"source":"family","target":"food","value":2000},{"source":"family","target":"childcare","value":5500},{"source":"family","target":"other","value":500},{"source":"flexible","target":"food","value":1000},{"source":"flexible","target":"other","value":7500}],"period_label":"a typical month"},"features":[{"kind":"main_path","marks":["link:salary->commitments","node:salary"],"slots":{"subject":"Household income","source":"Salary","target":"Commitments","value":"11,000 CNY a month","share":"50 percent","pct":"50","period":"a typical month","unit":"¥"},"auto":false,"id":"bud-main","examples":[{"en":"Salary sends 11,000 CNY a month to commitments, half of the 22,000 it brings in.","zh":"工资每月把 11,000 元送进固定支出，占 22,000 元收入的一半。"}],"note_zh":"flow from X to Y；half of + 整体，说明这条线占来源的一半。","interpret_zh":"收入的一半先进入固定支出，剩下的才分给家庭和弹性消费。"},{"kind":"secondary_path","marks":["link:salary->family","link:salary->flexible"],"slots":{"subject":"Household income","source":"Salary","target":"Family","value":"5,500 CNY a month","share":"25 percent","pct":"25","period":"a typical month","unit":"¥"},"auto":false,"id":"bud-second","examples":[{"en":"Salary also pays 5,500 to family costs and 5,500 to flexible spending.","zh":"工资还给家庭支出 5,500 元，给弹性支出 5,500 元。"}],"note_zh":"a share of / a slice of 描述次要流向；两条线数值相同。","interpret_zh":"工资的另外四分之一给了家庭，四分之一留给弹性消费。"},{"kind":"split","marks":["link:partner->family","link:partner->commitments","link:partner->flexible","node:partner"],"slots":{"subject":"Household income","source":"Partner income","target":"Commitments","value":"2,000 CNY a month","share":"31 percent","pct":"31","period":"a typical month","unit":"¥"},"auto":false,"id":"bud-partner","examples":[{"en":"Partner income of 6,500 splits into 2,500 for family, 2,000 for commitments, and 2,000 for flexible spending.","zh":"伴侣的 6,500 元收入分成三份：家庭 2,500，固定支出 2,000，弹性支出 2,000。"}],"note_zh":"split into + 三项，按数值从大到小排；三份之和等于总量。","interpret_zh":"伴侣收入更偏家庭，和工资的分配顺序不同。"},{"kind":"secondary_path","marks":["link:freelance->commitments"],"slots":{"subject":"Household income","source":"Freelance","target":"Commitments","value":"500 CNY a month","share":"33 percent","pct":"33","period":"a typical month","unit":"¥"},"auto":true},{"kind":"main_path","marks":["link:freelance->flexible"],"slots":{"subject":"Household income","source":"Freelance","target":"Flexible","value":"1,000 CNY a month","share":"67 percent","pct":"67","period":"a typical month","unit":"¥"},"auto":true},{"kind":"main_path","marks":["link:commitments->rent","node:commitments","node:rent"],"slots":{"subject":"Household income","source":"Commitments","target":"Rent","value":"9,000 CNY a month","share":"67 percent","pct":"67","period":"a typical month","unit":"¥"},"auto":false,"id":"bud-rent","examples":[{"en":"Of the 13,500 in commitments, rent takes 9,000, about two thirds.","zh":"固定支出 13,500 元里，房租拿走 9,000 元，约三分之二。"}],"note_zh":"of + 整体前置；two thirds 是分数，比 percent 更能读出分量。","interpret_zh":"固定支出里房租占大头，剩下的水电和交通只是零头。"},{"kind":"secondary_path","marks":["link:commitments->utilities","link:commitments->transport","link:family->other","node:utilities","node:transport"],"slots":{"subject":"Household income","source":"Commitments","target":"Utilities","value":"1,300 CNY a month","share":"10 percent","pct":"10","period":"a typical month","unit":"¥"},"auto":false,"id":"bud-small","examples":[{"en":"The smaller lines are utilities at 1,300, transport at 1,700, and other family costs at 500.","zh":"较小的几条线是水电 1,300 元、交通 1,700 元、家庭其他支出 500 元。"}],"note_zh":"a small share / smaller lines；列举多个数值时按从大到小或从小到大排。","interpret_zh":"这几项合计 3,500 元，约占预算的 12%，单看都不起眼。"},{"kind":"merge","marks":["link:commitments->food","link:family->food","link:flexible->food","node:food"],"slots":{"subject":"Household income","source":"Commitments","target":"Food","value":"1,500 CNY a month","share":"11 percent","pct":"11","period":"a typical month","unit":"¥"},"auto":false,"id":"bud-food","examples":[{"en":"Food draws 2,000 from family, 1,500 from commitments, and 1,000 from flexible spending, for 4,500 in total.","zh":"餐饮从家庭支出拿 2,000，从固定支出拿 1,500，从弹性支出拿 1,000，合计 4,500 元。"}],"note_zh":"come together at / draw from；三个来源汇合到一个节点。","interpret_zh":"餐饮由三块预算共同承担，看单项占比时别只盯一个来源。"},{"kind":"main_path","marks":["link:family->childcare","node:family","node:childcare"],"slots":{"subject":"Household income","source":"Family","target":"Childcare","value":"5,500 CNY a month","share":"69 percent","pct":"69","period":"a typical month","unit":"¥"},"auto":false,"id":"bud-family","examples":[{"en":"Family costs take 8,000, and childcare alone is 5,500 of that.","zh":"家庭支出共 8,000 元，其中育儿一项就有 5,500 元。"}],"note_zh":"the main destination / alone 强调单项在整块里的比重。","interpret_zh":"育儿占家庭支出的近七成，是这一块里最难压缩的部分。"},{"kind":"main_path","marks":["link:flexible->other"],"slots":{"subject":"Household income","source":"Flexible","target":"Other","value":"7,500 CNY a month","share":"88 percent","pct":"88","period":"a typical month","unit":"¥"},"auto":true},{"kind":"split","marks":["node:freelance"],"slots":{"subject":"Household income","source":"Freelance","target":"Flexible","category":"Freelance","value":"1,500 CNY a month","share":"67 percent","pct":"67","period":"a typical month","unit":"¥"},"auto":true},{"kind":"split","marks":["node:flexible"],"slots":{"subject":"Household income","source":"Flexible","target":"Other","category":"Flexible","value":"8,500 CNY a month","share":"88 percent","pct":"88","period":"a typical month","unit":"¥"},"auto":true},{"kind":"merge","marks":["node:other"],"slots":{"subject":"Household income","source":"Flexible","target":"Other","category":"Other","value":"8,000 CNY a month","share":"27 percent","pct":"27","period":"a typical month","unit":"¥"},"auto":true}],"overview_zh":"月收入 30,000 元分成三块：固定支出 13,500、家庭 8,000、弹性 8,500。房租和育儿是最大的两个去向，餐饮由三块共同承担。流向图只看分配，图里没有储蓄项。","descriptions":{"general":{"a2":"Salary is the biggest income, at 22,000 CNY a month. Most of it goes to commitments, which pay for rent. Rent takes 9,000, the largest single cost.","b1":"Monthly income of 30,000 CNY flows into three blocks: commitments at 13,500, family at 8,000, and flexible spending at 8,500. Rent takes 9,000 of the commitments block, while childcare absorbs 5,500 of family spending.","b2":"Household income of 30,000 CNY a month divides into commitments, family, and flexible spending at 13,500, 8,000, and 8,500 respectively. Rent alone accounts for 9,000, or two thirds of commitments. Food is funded from all three blocks and totals 4,500, while childcare takes 5,500."},"ielts":"Household income totaled 30,000 CNY a month, of which commitments received 13,500, family spending 8,000, and flexible spending 8,500. Rent was the largest single outflow at 9,000, followed by childcare at 5,500 and food at 4,500.","business":"Half of the salary goes straight into commitments, and rent alone absorbs 9,000 a month. Childcare is the largest family cost at 5,500. Flexible spending of 8,500 is where cuts are easiest, with 7,500 of it going to other costs."}},{"id":"shares","type":"pie","label_zh":"支出构成","label_en":"Spending mix","subject":"Monthly household spending","subtitle_en":"How monthly spending splits across categories.","unit":{"en":"percent","short":"%","decimals":1,"kind":"percent","points":true},"data":{"parts":[{"id":"rent","name_en":"Rent","name_zh":"房租","slot":1,"value":30},{"id":"other","name_en":"Other","name_zh":"其他","slot":2,"value":26.7},{"id":"childcare","name_en":"Childcare","name_zh":"育儿","slot":3,"value":18.3},{"id":"food","name_en":"Food","name_zh":"餐饮","slot":4,"value":15},{"id":"transport","name_en":"Transport","name_zh":"交通","slot":5,"value":5.7},{"id":"utilities","name_en":"Utilities","name_zh":"水电","slot":6,"value":4.3}]},"features":[{"kind":"largest_share","marks":["slice:rent"],"slots":{"subject":"Monthly household spending","category":"Rent","share":"30 percent","share_number":"30","value":"30 percent","rank":"1"},"auto":false,"id":"pie-rent","examples":[{"en":"Rent is the largest slice, at 30 percent of spending.","zh":"房租是最大的一块，占支出的 30%。"}],"note_zh":"the largest slice / the largest share；30% 不到三分之一，别写成 a third。","interpret_zh":"房租是最大单项，但用了不到三分之一的预算。"},{"kind":"combined_share","marks":["slice:other","slice:childcare"],"slots":{"subject":"Monthly household spending","category":"Other","share":"26.7 percent","share_number":"26.7","value":"26.7 percent","rank":"2"},"auto":false,"id":"pie-combined","examples":[{"en":"Other costs and childcare together make up 45 percent of spending.","zh":"其他支出和育儿合计占支出的 45%。"}],"note_zh":"together / combined + make up；合计超过单一最大项。","interpret_zh":"其他是一个合并项，和单一类别比时要小心。"},{"kind":"compare_shares","marks":["slice:food"],"slots":{"subject":"Monthly household spending","category":"Food","share":"15 percent","share_number":"15","value":"15 percent","rank":"4"},"auto":false,"id":"pie-compare","examples":[{"en":"Food is 15 percent, about half the size of rent.","zh":"餐饮占 15%，大约是房租的一半。"}],"note_zh":"half the size of / twice as large as；比较份额用 as…as 结构。","interpret_zh":"餐饮只有房租的一半，但它是三块预算共同承担的。"},{"kind":"item","marks":["slice:transport"],"slots":{"subject":"Monthly household spending","category":"Transport","share":"5.7 percent","share_number":"5.7","value":"5.7 percent","rank":"5"},"auto":false,"id":"pie-item","examples":[{"en":"Transport accounts for 5.7 percent of spending.","zh":"交通占支出的 5.7%。"}],"note_zh":"account for + 百分比，是描述占比最稳的动词短语。","interpret_zh":"交通占比小，但通勤是每天发生的固定开销。"},{"kind":"smallest_share","marks":["slice:utilities"],"slots":{"subject":"Monthly household spending","category":"Utilities","share":"4.3 percent","share_number":"4.3","value":"4.3 percent","rank":"6"},"auto":false,"id":"pie-small","examples":[{"en":"Utilities are the smallest slice, at just 4.3 percent.","zh":"水电是最小的一块，只有 4.3%。"}],"note_zh":"the smallest slice；just 强调低于预期。","interpret_zh":"水电占比最小，也最难再压缩。"}],"overview_zh":"支出里房租 30% 最大，其他合并项 26.7% 紧跟，育儿 18.3%，餐饮 15%。交通和水电合计只有 10%，但这两项几乎每月固定。","descriptions":{"general":{"a2":"Rent is the biggest part, at 30 percent of spending. Childcare is 18.3 percent, and food is 15 percent. Transport and utilities are small. Other costs make up the rest.","b1":"Rent accounts for 30 percent of monthly spending, the largest share. Other costs and childcare follow at 26.7 and 18.3 percent, while food makes up 15 percent and transport just 5.7.","b2":"Monthly spending is led by rent at 30 percent, followed by other costs at 26.7 and childcare at 18.3. Food takes 15 percent, about half the rent share, while transport and utilities together account for just 10 percent."},"ielts":"Rent represented the largest share of monthly spending at 30 percent, followed by other costs at 26.7 percent and childcare at 18.3 percent. Food accounted for 15 percent, while transport and utilities made up 5.7 and 4.3 percent respectively.","business":"Rent is the single largest block at 30 percent, and childcare adds another 18.3. Together they take nearly half the budget. Food at 15 percent is spread across three funding blocks, while transport and utilities are small but hard to cut."}}]};
